(()=>{'use strict';const data=window.ATLAS_CAREER,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let chosenSkill='',track='story',progress={},draft={};const storage='atlas-career-work-v1';try{const saved=JSON.parse(localStorage.getItem(storage)||'{}');progress=saved.progress&&typeof saved.progress==='object'?saved.progress:{};draft=saved.draft&&typeof saved.draft==='object'?saved.draft:{};}catch{}const job=id=>data.jobs.find(j=>j.id===id);function save(){try{localStorage.setItem(storage,JSON.stringify({version:1,progress,draft}));return true;}catch{return false;}}function download(name,obj){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);}const directions={story:'<b>建议优先：叙事型网页设计。</b> Factory 明确列出滚动叙事、交互产品演示及完整上线。你的兴趣与这条方向相邻；目前最需要补的是原创项目、个人贡献、验证与交付证据。来源：<a href="#job-factory">Factory 原文拆解 ↗</a>',ux:'<b>产品交互方向：先补研究与完整流程。</b> 把双视角模板变成用户旅程，记录错误、等待、恢复和结果。炫酷效果不能直接证明研究能力。来源：<a href="#job-xinxisoft">UI/UX（GT）岗位 ↗</a>',motion:'<b>品牌 / 三维方向：从单段效果走向制作系统。</b> 动效规范、分镜和真实制作工程需要一起展示。网页程序化模型不能替代 C4D 或 AE 能力证明。来源：<a href="#job-bns">Brand New School ↗</a> · <a href="#job-isoftstone">软通动力 ↗</a>'};function renderTasks(){ $('#direction').innerHTML=directions[track];$('#tasks').innerHTML=data.tasks.map(t=>'<article class="task"><span class="priority">'+t.priority+' / 练习建议</span><h3>'+esc(t.title)+'</h3><p>'+esc(t.subtitle)+'</p><p class="question">自问：'+esc(t.question)+'</p>'+t.checks.map((c,i)=>'<label><input type="checkbox" data-check="'+t.id+'-'+i+'" '+(progress[t.id+'-'+i]?'checked':'')+'>'+esc(c)+'</label>').join('')+'<div class="sources">'+t.sources.map(id=>'<a href="#job-'+id+'">依据：'+esc(job(id).company)+'</a>').join('')+'</div><p>'+esc(t.deliverable)+'</p><a href="library.html?item='+t.template+'#collection">打开对应模板 ↗</a></article>').join('');updateProgress();}function updateProgress(){const keys=data.tasks.flatMap(t=>t.checks.map((_,i)=>t.id+'-'+i));$('#progress').textContent=keys.filter(k=>progress[k]===true).length+' / '+keys.length+' 项自记进展 · 勾选代表你自行记录完成，不是能力评分或招聘匹配度。';}function filtered(){const q=$('#job-search').value.toLowerCase(),region=$('#region').value;return data.jobs.filter(j=>(region==='all'||j.region===region)&&JSON.stringify([j.company,j.title,j.requirements,j.location,j.skills.map(s=>data.skills.find(x=>x[0]===s)?.[1])]).toLowerCase().includes(q));}function renderJobs(){const base=filtered();$('#skills').innerHTML=data.skills.map(([id,label])=>{const n=base.filter(j=>j.skills.includes(id)).length;return '<button data-skill="'+id+'" aria-pressed="'+(chosenSkill===id)+'">'+label+' '+n+'/'+base.length+'</button>';}).join('');$('#clear-skill').hidden=!chosenSkill;const found=base.filter(j=>!chosenSkill||j.skills.includes(chosenSkill));$('#jobs').innerHTML=found.length?found.map(j=>'<article class="job" id="job-'+j.id+'"><span class="tag">'+esc(j.region+' / '+j.source)+'</span><h3>'+esc(j.title)+'</h3><b>'+esc(j.company)+'</b><p class="meta">'+esc(j.location)+'<br>'+esc(j.level)+'<br>'+esc(j.published)+'<br>核对：'+j.checked+' · '+esc(j.verified)+'</p><blockquote>原文短摘：“'+esc(j.quote)+'”</blockquote><ul>'+j.requirements.map(([kind,text])=>'<li><b>'+esc(kind)+'：</b>'+esc(text)+'</li>').join('')+'</ul><p class="analysis"><b>对素材库的启发 · 分析：</b>'+esc(j.implication)+'</p><a href="'+esc(j.url)+'" target="_blank" rel="noopener">查看原始岗位 ↗</a><p class="meta">'+esc(j.status)+'</p></article>').join(''):'<p>没有符合筛选的样本。清除关键词或切换地区。</p>';}
document.addEventListener('click',e=>{const anchor=e.target.closest('a[href^="#job-"]');if(anchor){e.preventDefault();chosenSkill='';$('#region').value='all';$('#job-search').value='';renderJobs();document.querySelector(anchor.getAttribute('href'))?.scrollIntoView({behavior:'smooth'});}const t=e.target.closest('[data-track]');if(t){track=t.dataset.track;document.querySelectorAll('[data-track]').forEach(b=>b.setAttribute('aria-pressed',String(b===t)));renderTasks();}const s=e.target.closest('[data-skill]');if(s){chosenSkill=chosenSkill===s.dataset.skill?'':s.dataset.skill;renderJobs();}});document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){progress[e.target.dataset.check]=e.target.checked;const ok=save();updateProgress();if(!ok)$('#progress').textContent+=' 保存失败，请导出草稿备份。';}});$('#region').onchange=()=>{chosenSkill='';renderJobs();};$('#job-search').oninput=renderJobs;$('#clear-skill').onclick=()=>{chosenSkill='';renderJobs();};$('#excluded').innerHTML=data.excluded.map(x=>'<p><a href="'+esc(x.url)+'" target="_blank" rel="noopener">'+esc(x.company+' / '+x.title)+' ↗</a><br>'+esc(x.reason)+' 核对：'+x.checked+'</p>').join('');const fields=['title','track','problem','contribution','logic','reason','validation','outcome','links'],labels=['项目名称','目标方向','用户与问题','你的贡献','交互与叙事逻辑','依据与取舍','验证记录','结果与局限','作品与证据链接'];function readDraft(){const f=new FormData($('#case-form'));draft=Object.fromEntries(fields.map(k=>[k,String(f.get(k)||'').slice(0,12000)]));return draft;}function fillDraft(){fields.forEach(k=>{if(typeof draft[k]==='string')$('#case-form').elements[k].value=draft[k];});}$('#case-form').onsubmit=e=>{e.preventDefault();readDraft();$('#case-status').textContent=save()?'已保存在当前浏览器。建议导出备份。':'浏览器保存失败，请导出备份。';};$('#export-case').onclick=()=>{readDraft();download('atlas-case-workbook.json',{version:1,draft,progress,sourceDate:data.checked,exportedAt:new Date().toISOString()});$('#case-status').textContent='已导出案例草稿与自记进展。';};$('#import-case').onclick=()=>$('#case-file').click();$('#case-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>300000)throw Error('文件过大');const raw=JSON.parse(await f.text());if(raw.version!==1||!raw.draft||typeof raw.draft!=='object')throw Error('格式不正确');const incoming=Object.fromEntries(fields.filter(k=>typeof raw.draft[k]==='string').map(k=>[k,raw.draft[k].slice(0,12000)]));draft={...draft,...incoming};data.tasks.forEach(t=>t.checks.forEach((_,i)=>{const k=t.id+'-'+i;if(typeof raw.progress?.[k]==='boolean')progress[k]=raw.progress[k];}));fillDraft();renderTasks();$('#case-status').textContent=save()?'导入完成；同名字段以导入内容为准。':'已导入当前页面，但浏览器保存失败。';}catch(err){$('#case-status').textContent='导入失败：'+err.message;}finally{e.target.value='';}};$('#print-case').onclick=()=>{readDraft();$('#print-report').innerHTML='<h1>'+esc(draft.title||'未命名案例草稿')+'</h1><p>ATLAS 案例工作簿 · 用户自行填写 · 招聘依据核对日期 '+data.checked+'</p>'+fields.slice(1).map((k,i)=>'<h2>'+labels[i+1]+'</h2><p>'+esc(draft[k]||'尚未填写 / 无证据')+'</p>').join('')+'<h2>引用的岗位来源</h2>'+data.jobs.map(j=>'<p>'+esc(j.company+' · '+j.title)+'<br>'+esc(j.url)+'</p>').join('');window.print();};fillDraft();renderTasks();renderJobs();})();
